def solve(nums, k):
    min_val, max_val = min(nums), max(nums)
    count = [0] * (max_val - min_val + 1)
    for num in nums:
        count[num - min_val] += 1
    for i in range(len(count)):
        if count[i] >= k:
            return min_val + i
        k -= count[i]
