def solve(nums, k):
    for i in range(len(nums), 0, -1):
        min_idx = i - 1
        for j in range(i - 1):
            if nums[j] < nums[min_idx]:
                min_idx = j
        nums[i - 1], nums[min_idx] = nums[min_idx], nums[i - 1]
    return nums[k - 1]
