                nums[store_idx], nums[i] = nums[i], nums[store_idx]
                store_idx += 1
        nums[right], nums[store_idx] = nums[store_idx], nums[right]
        return store_idx

    def random_quickselect(left, right, k):
        if left == right:
            return nums[left]
        pivot_idx = random.randint(left, right)
        pivot_idx = partition(left, right, pivot_idx)
        if k == pivot_idx:
            return nums[pivot_idx]
        elif k < pivot_idx:
            return random_quickselect(left, pivot_idx - 1, k)
        else:
            return random_quickselect(pivot_idx + 1, right, k)

    return random_quickselect(0, len(nums) - 1, k)
