import random

def solve(nums, k):
    def quickselect(start, end, k):
        pivot = random.randint(start, end)
        nums[start], nums[pivot] = nums[pivot], nums[start]
        pivot_val = nums[start]
        left, right = start, end
        while left < right:
            while left < right and nums[right] >= pivot_val:
                right -= 1
            nums[left] = nums[right]
            while left < right and nums[left] <= pivot_val:
                left += 1
            nums[right] = nums[left]
        nums[left] = pivot_val
        if k == left - start + 1:
            return nums[left]
        elif k < left - start + 1:
            return quickselect(start, left - 1, k)
        else:
            return quickselect(left + 1, end, k - (left - start + 1))
    return quickselect(0, len(nums) - 1, k)
