import math

def solve(nums, k):
    def median_of_medians(arr):
        if len(arr) <= 5:
            return sorted(arr)[len(arr) // 2]
        subarrays = [arr[i*5:(i+1)*5] for i in range((len(arr)+4) // 5)]
        medians = [median_of_medians(sub) for sub in subarrays]
        return median_of_medians(medians)

    def partition(arr, pivot):
        left = [x for x in arr if x < pivot]
        middle = [x for x in arr if x == pivot]
        right = [x for x in arr if x > pivot]
        return left + middle + right

    def select(arr, k):
        if len(arr) == 1:
            return arr[0]
        pivot = median_of_medians(arr)
        partitioned = partition(arr, pivot)
        if k <= len(partitioned[0]):
            return select(partitioned[0], k)
        elif k <= len(partitioned[0]) + len(partitioned[1]):
            return pivot
        else:
            return select(partitioned[2], k - len(partitioned[0]) - len(partitioned[1]))

    return select(nums, k)
