        return 0
    from collections import deque
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        if w == 0:  # Only consider unweighted edges (weight 0)
            adj[u].append(v)
    visited = [False] * n
    q = deque()
    q.append((s, 0))
    visited[s] = True
    while q:
        node, dist = q.popleft()
        for neighbor in adj[node]:
            if not visited[neighbor]:
                if neighbor == t:
                    return dist + 1
                visited[neighbor] = True
                q.append((neighbor, dist + 1))
    return -1
