    def heuristic(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    visited = set()
    priority_queue = []
    heapq.heappush(priority_queue, (0, start, [start]))

    while priority_queue:
        cost, current, path = heapq.heappop(priority_queue)
        current_row, current_col = current

        if current == goal:
            return path

        if current in visited:
            continue

        visited.add(current)

