import random

def solve(nums, k):
    def introselect(arr, k):
        if k == 1:
            return min(arr)
        elif k == len(arr):
            return max(arr)
        else:
            # Use median of medians to find a good pivot
            def median_of_medians(arr):
                if len(arr) <= 5:
                    return sorted(arr)[len(arr) // 2]
                medians = [median_of_medians(arr[i:i+5]) for i in range(0, len(arr), 5)]
                return median_of_medians(medians)

            pivot = median_of_medians(arr)
            left = [x for x in arr if x < pivot]
            mid = [x for x in arr if x == pivot]
            right = [x for x in arr if x > pivot]

            if k <= len(left):
                return introselect(left, k)
            elif k <= len(left) + len(mid):
                return pivot
            else:
                return introselect(right, k - len(left) - len(mid))

    return introselect(nums, k)
