def solve(nums, k):
    def merge_sort_select(arr, k):
        if len(arr) <= 1:
            return arr[0]
        mid = len(arr) // 2
        left = merge_sort_select(arr[:mid], k)
        right = merge_sort_select(arr[mid:], k)
        if left <= right:
            return left
        else:
            return right

    def merge_sort(arr):
        if len(arr) <= 1:
            return arr
        mid = len(arr) // 2
        left = merge_sort(arr[:mid])
        right = merge_sort(arr[mid:])
        merged = []
        i = j = 0
        while i < len(left) and j < len(right):
            if left[i] <= right[j]:
                merged.append(left[i])
                i += 1
            else:
                merged.append(right[j])
                j += 1
        merged.extend(left[i:])
        merged.extend(right[j:])
        return merged

    sorted_nums = merge_sort(nums)
    return sorted_nums[k - 1]
