        for neighbor, weight in adj[node]:
            new_cost = cost + weight
            if new_cost < visited[neighbor]:
                visited[neighbor] = new_cost
                heapq.heappush(pq, (new_cost + heuristic(neighbor), neighbor, new_cost))

    return -1
