def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Heuristic function: Manhattan distance (can be replaced with other heuristics)
    def heuristic(u):
        return abs(u - t)

    # Priority queue: (current_distance + heuristic, current_node, current_distance)
    pq = [(heuristic(s), s, 0)]
    visited = [False] * n
    distances = [float('inf')] * n
    distances[s] = 0

    while pq:
        h, u, dist = heapq.heappop(pq)
        if visited[u]:
            continue
        visited[u] = True

        if u == t:
            return dist

        for v, weight in adj[u]:
            if distances[v] > dist + weight:
                distances[v] = dist + weight
                heapq.heappush(pq, (distances[v] + heuristic(v), v, distances[v]))

    return -1
