import heapq

def solve(grid, start, goal):
    if not grid or start == goal:
        if grid[start[0]][start[1]] == '.':
            return [start]
        return []

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = set()
    heap = [(0, start[0], start[1])]

    while heap:
        _, r, c = heapq.heappop(heap)
        if (r, c) == goal:
            path = []
            while (r, c) != start:
                path.append((r, c))
                r, c = prev[(r, c)]
            path.append(start)
            return path[::-1]
        if (r, c) in visited:
            continue
        visited.add((r, c))
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                heapq.heappush(heap, (abs(nr - goal[0]) + abs(nc - goal[1]), nr, nc))
                prev[(nr, nc)] = (r, c)

    return []
