def solve(grid, start, goal):
    if not grid or start == goal:
        if is_free(grid, start):
            return [start]
        else:
            return []

    rows, cols = len(grid), len(grid[0])
    path = []
    visited = set()

    def is_free(cell):
        r, c = cell
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    def backtrack(current):
        if current == goal:
            path.append(list(current))
            return True
        if current in visited:
            return False
        visited.add(current)
        r, c = current
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_free((nr, nc)):
                if backtrack((nr, nc)):
                    path.append(list(current))
                    return True
        visited.remove(current)
        return False

    if backtrack(start):
        return path
    else:
        return []

def is_free(grid, cell):
    r, c = cell
    return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'
