import heapq

def solve(grid, start, goal):
    if not grid or start == goal:
        if grid[start[0]][start[1]] == '#':
            return []
        return [start]

    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = set()
    priority_queue = [(0, start[0], start[1])]
    came_from = {}
    dist = { (start[0], start[1]): 0 }

    while priority_queue:
        cost, row, col = heapq.heappop(priority_queue)
        if (row, col) == goal:
            break
        if (row, col) in visited:
            continue
        visited.add((row, col))
        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == '.' and (nr, nc) not in visited:
                new_cost = cost + 1
                if (nr, nc) not in dist or new_cost < dist[(nr, nc)]:
                    dist[(nr, nc)] = new_cost
                    came_from[(nr, nc)] = (row, col)
                    heapq.heappush(priority_queue, (new_cost, nr, nc))

    if goal not in came_from:
        return []

    path = []
    current = goal
    while current != start:
        path.append(current)
        current = came_from[current]
    path.append(start)
    return path[::-1]
