from heapq import heappush, heappop

def solve(grid, start, goal):
    if start == goal:
        return [start]
    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if grid[start_row][start_col] == '#' or grid[goal_row][goal_col] == '#':
        return []

    def heuristic(pos):
        r, c = pos
        return abs(r - goal_row) + abs(c - goal_col)

    visited = set()
    priority_queue = []
    heappush(priority_queue, (heuristic(start), start))
    came_from = {}

    while priority_queue:
        _, current = heappop(priority_queue)
        if current in visited:
            continue
        visited.add(current)
        r, c = current
        if current == goal:
            break
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == '.' and (nr, nc) not in visited:
                    came_from[(nr, nc)] = current
                    heappush(priority_queue, (heuristic((nr, nc)), (nr, nc)))

    if goal not in came_from:
        return []

    path = [goal]
    while path[-1] != start:
        path.append(came_from[path[-1]])

    return path[::-1]
