from collections import deque

def solve(grid, start, goal):
    if not grid or start == goal:
        if grid[start[0]][start[1]] == '#':
            return []
        return [start]

    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if grid[start_row][start_col] == '#' or grid[goal_row][goal_col] == '#':
        return []

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and grid[r][c] == '.'

    # Bidirectional BFS
    queue_start = deque([(start_row, start_col, [start])])
    visited_start = set([(start_row, start_col)])

    queue_goal = deque([(goal_row, goal_col, [goal])])
    visited_goal = set([(goal_row, goal_col)])

    while queue_start and queue_goal:
        # Expand from start
        for _ in range(len(queue_start)):
            r, c, path = queue_start.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc) and (nr, nc) not in visited_start:
                    new_path = path + [(nr, nc)]
                    if (nr, nc) in visited_goal:
                        return new_path
                    visited_start.add((nr, nc))
                    queue_start.append((nr, nc, new_path))

        # Expand from goal
        for _ in range(len(queue_goal)):
            r, c, path = queue_goal.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if is_valid(nr, nc) and (nr, nc) not in visited_goal:
                    new_path = path + [(nr, nc)]
                    if (nr, nc) in visited_start:
                        return new_path
                    visited_goal.add((nr, nc))
                    queue_goal.append((nr, nc, new_path))

    return []
